import{_ as a,o as t,c as n,a6 as o}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"Organize automations","description":"","frontmatter":{"title":"Organize automations","docId":"user.automations.index","translationKey":"user.automations.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","translationRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","order":10},"headers":[],"relativePath":"en/user/automations/index.md","filePath":"en/user/automations/index.md","lastUpdated":1794611623000}'),r={name:"en/user/automations/index.md"};function i(s,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="organize-automations" tabindex="-1">Organize automations <a class="header-anchor" href="#organize-automations" aria-label="Permalink to &quot;Organize automations {#organize-automations}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Build a small, understandable library that responds to LIVE events. You need a working desktop host. A real <a href="./../live/connections.html">LIVE connection</a> is needed to validate upstream events; plugin actions also require their plugin and service to be ready.</p><h2 id="understand-the-library" tabindex="-1">Understand the library <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to &quot;Understand the library {#understand-the-library}&quot;">​</a></h2><p>An <strong>Action</strong> is a reusable configured operation, such as writing a log line or playing a sound. An <strong>Event</strong> chooses a trigger, filters, cooldown and linked actions. A profile groups definitions for a workflow; only one profile pack is active at a time. Runtime <a href="./variables.html">Variables</a> supply values that several actions can reuse.</p><ol><li>Open <strong>Automations</strong> and confirm the active profile before editing. Search Events and Actions separately so you know which kind of record you are selecting.</li><li>Begin with the <a href="./first-rule.html">first logging rule</a>. Create its action, then an event that references it.</li><li>Choose a trigger supported by the current host. Use the field picker to add filters for that trigger. Multiple conditions narrow matching; they do not change the incoming payload.</li><li>Set a cooldown and its scope. A global cooldown limits the rule across viewers; a per-user cooldown tracks viewers separately.</li><li>Link the intended actions in order. The normal mode runs the chosen list; random mode selects an action from it. A delay action postpones later actions rather than slowing LIVE ingestion.</li><li>Save, review any displayed definition changes, then explicitly enable the records you intend to run. Check the run history for the action name, outcome and error.</li></ol><p>Tests can execute the configured effects. Read the selected action list before pressing <strong>Test</strong> or firing an event, especially for audio, HTTP, points and plugin operations. Use logging while learning.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Local editing, execution, templates, profiles and history are available. Plugin triggers appear only while their supporting plugin is installed and enabled. Activation depends on the import surface and reviewed enabled values; inspect both events and actions before confirming. The Events/Actions <strong>Changes</strong> panel is a <a href="./../cloud/changes.html">local reference comparison</a>, not automatic Cloud upload.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For no run, check active profile, enabled states, trigger, filters, cooldown and missing actions in that order. For a revision conflict, read the current saved definition and review again. Do not overwrite another person&#39;s update blindly. Export a known-good <a href="./templates.html">profile</a> before broad changes.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Before changing profiles or importing, read the <a href="./templates.html#operational-details">activation rules by surface</a>. Profile switching can enable members that you had individually disabled. Cooldown state is in memory, capped at 24 hours; missing viewer uniqueId shares one anonymous scope. The table clears when it reaches 8,192 retained keys, so overload or restart can allow extra runs. It is not a durable quota or replay guarantee.</p>',13)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
